  const gaps: number[][] = [];
  let busyUntil = all[0][1];
  for (const [s, e] of all) {
    if (s > busyUntil) gaps.push([busyUntil, s]);
    busyUntil = Math.max(busyUntil, e);
  }
  return gaps;
