class MinHeap {
  private a: [number, number, number][] = []; // [start, person, index]
  get size() { return this.a.length; }
  push(x: [number, number, number]) {
    const a = this.a; a.push(x);
    for (let i = a.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): [number, number, number] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      for (let i = 0; ;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function sharedFreeTime(schedules: number[][][]): number[][] {
  const heap = new MinHeap();
  schedules.forEach((cal, p) => heap.push([cal[0][0], p, 0]));
  const gaps: number[][] = [];
  let busyUntil = -1;
  while (heap.size) {
    const [s, p, i] = heap.pop();
    const e = schedules[p][i][1];
    if (busyUntil >= 0 && s > busyUntil) gaps.push([busyUntil, s]);
    busyUntil = Math.max(busyUntil, e);
    if (i + 1 < schedules[p].length) heap.push([schedules[p][i + 1][0], p, i + 1]);
  }
  return gaps;
}

