        heapq.heapify(heap)
        gaps = []
        busy_until = None
        while heap:
            s, p, i = heapq.heappop(heap)
            e = schedules[p][i][1]
            if busy_until is not None and s > busy_until:
                gaps.append([busy_until, s])
            busy_until = e if busy_until is None else max(busy_until, e)
            if i + 1 < len(schedules[p]):
                heapq.heappush(heap, (schedules[p][i + 1][0], p, i + 1))
        return gaps

